fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since a and b have the same length, we can safely zip and compare element-wise
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x <= y)
        .collect()
}